def select_safe_driver(supply_v):
    safe = []
    for name in ["DRV8833", "TB6612FNG"]:
        spec = DATASHEET_DRIVERS[name]
        if is_within_recommended_bounds(supply_v, spec["vm_min_v"], spec["vm_max_v"]):
